        settings.stream().map(SheetSetting::getKey).filter(k -> k.startsWith(TERMS + "-")).distinct()
                .forEach(k -> {
                    String grade = k.substring(TERMS.length() + 1);
                    Integer own = gradeTermsOn(grade, today);
                    if (own != null) {
                        out.put(grade, own);
                    }
                });
